//! Rust port of `tests/test11.cpp` from the immer test-suite.
//!
//! The original builds an `immer::vector<int>` one `push_back` at a time, sums
//! it, builds a second vector holding every element doubled, and prints both
//! sums. This file is a line-for-line translation; everything it leans on lives
//! in the modules under `src/`:
//!
//! * `immer::Vector` — the persistent vector re-implemented from scratch
//!   (bit-partitioned trie, branching factor 32, structural sharing).
//! * `cpp::stoi` — `std::stoi`, including its two exception cases.
//! * `cpp::cint` — `int` arithmetic with two's-complement wrap-around.
//!
//! The `#[path]` attributes let this one file be built either way:
//!
//! ```text
//! rustc -O test11.rs        # standalone
//! cargo build --release     # as the `test11` binary target
//! ```

#[path = "src/cpp/mod.rs"]
mod cpp;
#[path = "src/immer/mod.rs"]
mod immer;

use crate::cpp::cint::{self, CInt};
use crate::cpp::stoi::{stoi, terminate_with_uncaught_exception};
use crate::immer::Vector;

fn main() {
    // int n = (argc > 1) ? std::stoi(argv[1]) : 11;
    // `argv[1]` exists exactly when `argc > 1`.
    let n: CInt = match cpp::cli::arg(1) {
        Some(argument) => match stoi(&argument) {
            Ok(value) => value,
            // Uncaught in the original, so the process aborts with the C++
            // runtime's banner on stderr.
            Err(error) => terminate_with_uncaught_exception(error),
        },
        None => 11,
    };

    // auto v = immer::vector<int>{};
    // for (int i = 0; i < n; ++i) v = v.push_back(i + 1);
    let mut v: Vector<CInt> = Vector::new();
    let mut i: CInt = 0;
    while i < n {
        v = v.push_back(cint::add(i, 1));
        i = cint::add(i, 1);
    }

    // auto sum = 0; for (auto x : v) sum += x;
    let mut sum: CInt = 0;
    for x in &v {
        sum = cint::add(sum, *x);
    }

    // std::cout << sum << std::endl;
    println!("{}", sum);

    // auto v2 = immer::vector<int>{};
    // for (int i = 0; i < v.size(); ++i) v2 = v2.push_back(v[i] * 2);
    let mut v2: Vector<CInt> = Vector::new();
    for i in 0..v.size() {
        v2 = v2.push_back(cint::mul(v[i], 2));
    }

    // sum = 0; for (auto x : v2) sum += x;
    sum = 0;
    for x in &v2 {
        sum = cint::add(sum, *x);
    }

    // std::cout << sum << std::endl;
    println!("{}", sum);
}
=== Cargo.toml ===
[package]
name = "test11"
version = "1.0.0"
edition = "2021"
description = "Pure-Rust port of the immer test-suite's tests/test11.cpp"
publish = false

# The entry file lives in the package root, as required, and is shared with a
# bare `rustc test11.rs` build; the modules it pulls in via `#[path]` are under
# `src/`.
[[bin]]
name = "test11"
path = "test11.rs"

# No dependencies: the persistent vector, the `std::stoi` emulation and the C++
# integer semantics are all implemented on top of `std`.
[dependencies]

[profile.release]
opt-level = 3
=== immer/mod.rs ===
//! A from-scratch persistent vector, re-implementing the `immer::vector`
//! contract with nothing but the standard library.
//!
//! * [`vector::Vector`] — the immutable vector itself.
//! * [`node`] — the bit-partitioned trie nodes it is built from.
//! * [`iter`] — `O(n)` forward iteration.

pub mod iter;
pub mod node;
pub mod vector;

// `self::` keeps this resolvable under both the 2015 and 2021 editions, so the
// entry file builds with a bare `rustc test11.rs` as well as with Cargo.
pub use self::vector::Vector;
=== cpp/mod.rs ===
//! Small compatibility layer for the C++ semantics the port has to reproduce.
//!
//! * [`cint`] — `int` arithmetic, including overflow wrap-around.
//! * [`stoi`] — `std::stoi` prefix parsing and its two exception cases.
//! * [`cli`] — `argv` access.

pub mod cint;
pub mod cli;
pub mod stoi;
